def conv_norm(vmin=0, vmax=GROWTH_VMAX, split=GROWTH_SPLIT, split_frac=GROWTH_SPLIT_FRAC):
    """Piecewise colour normalisation: max colour spread over [0, split] s
    (split_frac of the bar) and compressed over [split, vmax] s. Defaults come
    from the GROWTH_* config constants -- tweak those to try other scales."""
    def fwd(x):
        x = np.asarray(x, float)
        return np.where(x <= split,
                        split_frac * (x - vmin) / (split - vmin),
                        split_frac + (1 - split_frac) * (x - split) / (vmax - split))
    def inv(y):
        y = np.asarray(y, float)
        return np.where(y <= split_frac,
                        vmin + y / split_frac * (split - vmin),
                        split + (y - split_frac) / (1 - split_frac) * (vmax - split))
    return mpl.colors.FuncNorm((fwd, inv), vmin=vmin, vmax=vmax)

