# 2. Load all H5 files of the set
# ----------------------------------------------------------------------------
def classify(filename, flows):
    stem = filename.lower()
    at_std = np.abs(np.asarray(flows) - STANDARD_FLOW) <= STANDARD_TOL
    if "_iter_" in stem:
        return "BO_ITER"
    if "_init_" in stem:
        return "BO_INIT"
    if "_sample_" in stem:
        return "STANDARD" if at_std.all() else "LHS"
    return "UNKNOWN"

def manip_of(filename):
    """S12-M04_sample_3 -> S12-M04 (works for flat layout)."""
    return re.split(r"_(?:sample|init|iter)_", filename)[0]

def load_session(root):
    """Return (df_scalar, spectra_dict). Each spectrum entry keyed by filename."""
    files = sorted(root.rglob("*.h5"))
    files = [f for f in files if "previous_samples" not in f.parts]
    rows, spectra = [], {}
    for fp in files:
        try:
            with h5py.File(fp, "r") as f:
                flows = f["conditions/flow_set"][()]
                lam   = f["spectra/lambda_max"][()]
                amx   = f["spectra/extinction_max"][()]
                ts    = [t.decode() if isinstance(t, bytes) else t
                         for t in f["spectra/timestamp"][()]]
                wl    = f["spectra/wavelength"][()]
                absb  = f["spectra/extinction"][()]
                meta  = dict(f["sample"].attrs)
                stat  = dict(f["result"].attrs)
            name  = fp.stem
            etype = classify(name, flows)
            try:
                tsec = (pd.to_datetime(ts) - pd.to_datetime(ts[0])).total_seconds().values
            except Exception:
                tsec = np.arange(len(lam), dtype=float)
            rows.append({
                "filename":   name,
                "manip":      manip_of(name),
                "sample_id":  meta.get("sample_id", ""),
                "timestamp":  meta.get("timestamp", ""),
                "exp_type":   etype,
                "Q1": flows[0], "Q2": flows[1], "Q3": flows[2],
                "Q4": flows[3], "Q5": flows[4],
                "Q_total":    float(np.sum(flows)),
                "lambda_max": float(stat.get("lambda_max_nm", lam[-1])),
                "abs_max":    float(stat.get("extinction_max", amx[-1])),
                "lmax_initial": float(lam[0]),
                "abs_initial":  float(amx[0]),
                "n_spectra":  len(lam),
                "growth_time_s": float(tsec[-1]),
            })
            spectra[name] = {"wl": wl, "abs": absb, "lam_ts": lam,
                             "abs_ts": amx, "t": tsec}
        except Exception as e:
            print(f"  skip {fp.name}: {e}")
    df = pd.DataFrame(rows)
    df["timestamp"] = pd.to_datetime(df["timestamp"], errors="coerce")
    df = df.sort_values(["manip", "timestamp"]).reset_index(drop=True)
    df["seq"] = np.arange(len(df))
    return df, spectra

def manip_colors(df):
    manips = sorted(df.manip.unique())
    return {m: PALETTE[i % len(PALETTE)] for i, m in enumerate(manips)}

# molar amounts proportional to Q_i * stock_i -> mechanistic ratios
def add_chem_features(df):
    mol = df[QCOLS].values * STOCK
    ag  = mol[:, 0]
    df["reductant_to_Ag"]      = (mol[:, 3] + mol[:, 4]) / ag
    df["NaBH4_to_Ag"]          = mol[:, 4] / ag
    df["nucleation_vs_growth"] = mol[:, 4] / np.where(mol[:, 3] == 0, np.nan, mol[:, 3])
    df["PVP_to_Ag"]            = mol[:, 1] / ag
    df["acid_to_Ag"]           = mol[:, 2] / ag
    return df

# Convergence time recomputed from the spectral time series, using the
# instrument's own termination criteria between consecutive spectra.
def convergence_time(sp, amp=AMP_THR, corr=CORR_THR, kmin=MIN_SPECTRA):
    """First elapsed time where consecutive spectra satisfy both criteria.

    Returns (time_s, index, status) with status in {'ok','never','too_short'}.
    """
    A   = np.asarray(sp["abs"])      # (n, n_wl) full spectra over time
    amx = np.asarray(sp["abs_ts"])   # (n,) abs_max over time
    t   = np.asarray(sp["t"])        # (n,) elapsed seconds
    n   = len(t)
    if n < kmin:
        return np.nan, n - 1, "too_short"
    for i in range(1, n):
        if (i + 1) < kmin:           # need >= kmin spectra acquired first
            continue
        d_amp = abs(amx[i] - amx[i - 1]) / max(abs(amx[i - 1]), 1e-9)
        r = np.corrcoef(A[i], A[i - 1])[0, 1]
        if d_amp < amp and r > corr:
            return float(t[i]), i, "ok"
    return np.nan, n - 1, "never"

def flat_std(sp):
    """Std of the final absorbance spectrum across wavelengths (flatness)."""
    return float(np.asarray(sp["abs"][-1]).std())

def enrich_convergence(df, spectra):
    """Add recomputed convergence time and the flat-spectrum flag to df."""
    ct, idx, st = zip(*(convergence_time(spectra[f]) for f in df.filename))
    df["conv_time_s"] = ct
    df["conv_index"]  = idx
    df["conv_status"] = st
    df["abs_std"]     = [flat_std(spectra[f]) for f in df.filename]
    df["is_flat"]     = df.abs_std < FLAT_STD_THR
    return df

