def fig6_variogram(df):
    """lambda_max smoothness: |delta lambda| vs composition distance."""
    X = df[QCOLS].values; y = df.lambda_max.values; n = len(df)
    di, dl = [], []
    for a in range(n):
        for b in range(a + 1, n):
            di.append(np.linalg.norm(X[a] - X[b])); dl.append(abs(y[a] - y[b]))
    di, dl = np.array(di), np.array(dl)

    fig, ax = plt.subplots(1, 2, figsize=(11, 3.8))
    ax[0].scatter(di, dl, s=8, alpha=0.25, color="#0072B2", edgecolor="none")
    edges = np.linspace(0, di.max(), 13); cen = 0.5 * (edges[:-1] + edges[1:])
    means = [dl[(di >= edges[k]) & (di < edges[k + 1])].mean()
             if ((di >= edges[k]) & (di < edges[k + 1])).any() else np.nan
             for k in range(len(cen))]
    ax[0].plot(cen, means, "o-", color="#D55E00", lw=1.6, label="binned mean")
    ax[0].set_xlabel("Composition distance  ||$\\Delta Q$|| (uL/s)")
    ax[0].set_ylabel(r"$|\Delta \lambda_{\max}|$ (nm)")
    ax[0].set_title("(a) Empirical variogram"); ax[0].legend()

    feats = ["reductant_to_Ag", "NaBH4_to_Ag", "nucleation_vs_growth",
             "PVP_to_Ag", "acid_to_Ag"]
    labels = ["reductant/Ag", "NaBH4/Ag", "NaBH4/AscAcid", "PVP/Ag", "acid/Ag"]
    cors = [np.corrcoef(df[f], df.lambda_max)[0, 1] for f in feats]
    order = np.argsort(np.abs(cors))
    ax[1].barh([labels[k] for k in order], [cors[k] for k in order],
               color=["#D55E00" if cors[k] < 0 else "#0072B2" for k in order])
    ax[1].axvline(0, color="k", lw=0.8)
    ax[1].set_xlabel(r"Pearson $r$ with $\lambda_{\max}$")
    ax[1].set_title("(b) Mechanistic feature correlations"); ax[1].set_xlim(-1, 1)

    fig.suptitle(f"{DATASET}: composition -> $\\lambda_{{\\max}}$ structure",
                 y=1.03, fontsize=13, fontweight="bold")
    fig.tight_layout()
    return fig

def fig7_knn_local(df, k=5):
    """Local smoothness via k-nearest-neighbours in (standardised) composition.

    For each recipe we look at its k nearest neighbours in pump space and ask
    how much lambda_max varies among them. This isolates 'nearby points' and is
    not drowned by the dominant lambda_max mode (unlike the pairwise variogram).
    """
    Q = df[QCOLS].values
    Qz = (Q - Q.mean(0)) / Q.std(0)                 # standardise pumps
    y = df.lambda_max.values
    n = len(df)
    # pairwise distance matrix
    D = np.sqrt(((Qz[:, None, :] - Qz[None, :, :]) ** 2).sum(-1))
    np.fill_diagonal(D, np.inf)
    nn = np.argsort(D, axis=1)[:, :k]               # k nearest neighbours
    nn_mean = y[nn].mean(1)                          # mean lambda of neighbours
    local_std = y[nn].std(1)                         # local dispersion (nm)

    fig, ax = plt.subplots(1, 2, figsize=(11, 4.0))

    # (a) self vs neighbour-mean lambda_max, coloured by local dispersion
    sc = ax[0].scatter(y, nn_mean, c=local_std, cmap="magma_r", s=30,
                       edgecolor="white", linewidth=0.4)
    lims = [min(y.min(), nn_mean.min()) - 20, max(y.max(), nn_mean.max()) + 20]
    ax[0].plot(lims, lims, "k--", lw=1, label="y = x (perfectly smooth)")
    ax[0].set_xlim(lims); ax[0].set_ylim(lims)
    ax[0].set_xlabel(r"$\lambda_{\max}$ of the recipe (nm)")
    ax[0].set_ylabel(rf"mean $\lambda_{{\max}}$ of its {k} neighbours (nm)")
    ax[0].set_title("(a) Neighbour consistency")
    ax[0].legend(loc="upper left")
    cb = fig.colorbar(sc, ax=ax[0]); cb.set_label("local dispersion (nm)")

    # (b) distribution of local dispersion
    ax[1].hist(local_std, bins=20, color="#0072B2", alpha=0.85)
    ax[1].axvline(np.median(local_std), color="k", ls="--", lw=1)
    ax[1].text(0.97, 0.95,
               f"median = {np.median(local_std):.0f} nm\n"
               f"(noise floor among\nthe {k} closest recipes)",
               transform=ax[1].transAxes, ha="right", va="top", fontsize=9)
    ax[1].set_xlabel(rf"local $\lambda_{{\max}}$ dispersion among {k}-NN (nm)")
    ax[1].set_ylabel("Count")
    ax[1].set_title("(b) How much nearby recipes differ")

    fig.suptitle(f"{DATASET}: local smoothness of $\\lambda_{{\\max}}$ "
                 f"({k}-nearest-neighbour view)", y=1.03,
                 fontsize=13, fontweight="bold")
    fig.tight_layout()
    return fig

def compute_flat_boundary(df):
    """Midpoint between the highest-A_max flat spectrum and the lowest-A_max
    non-flat spectrum -- the empirical Ext_max threshold separating flats."""
    flat_max = df.loc[df.is_flat, "abs_max"].max()
    clean_min = df.loc[~df.is_flat, "abs_max"].min()
    return 0.5 * (flat_max + clean_min)

def compute_regimes(df, sphere_lmax=SPHERE_LMAX, disk_lmax=DISK_LMAX):
    """Data-driven annotation regimes for the Ext_max-vs-lambda_max scatter.

    'spheres': the dense low-lambda cluster (roughly monodisperse Ag nanospheres,
    single dipole plasmon ~400 nm) spans the full Ext_max range -> a vertical
    band. 'disks': the red-shifted population (anisotropic growth), where Ext_max
    tends to rise with lambda_max -> a shaded dispersion band (+-DISK_BAND_K
    residual std) along a linear fit. DISK_LMAX is intentionally a wide,
    qualitative "disk region" box (420-750 nm) rather than a narrow fit-optimised
    window -- by request, no r/slope annotation is drawn (DISK_SHOW_R=False);
    a fit is still computed internally to place/orient the band.
    Bounds/fit computed once on the non-flat population so both fig8 (with
    flats) and fig9 (flats removed) share identical, comparable annotations.
    """
    clean = df[~df.is_flat]
    dsk = clean[(clean.lambda_max >= disk_lmax[0]) & (clean.lambda_max <= disk_lmax[1])]
    slope, intercept = np.polyfit(dsk.lambda_max, dsk.abs_max, 1)
    r = np.corrcoef(dsk.lambda_max, dsk.abs_max)[0, 1]
    resid_std = float((dsk.abs_max - (slope * dsk.lambda_max + intercept)).std())
    return dict(sphere_lmax=sphere_lmax, disk_lmax=disk_lmax, disk_slope=slope,
               disk_intercept=intercept, disk_r=r, disk_resid_std=resid_std)

def scatter_amax_lmax(d, flat_boundary=None, regimes=None):
    """Ext_max vs lambda_max coloured by growth time (colour bar on the side).

    No figure title (publication style). y starts at 0. Growth-time colour scale
    is expanded over 0-20 s (most recipes) and compressed over 20-200 s. Optional
    annotations (from compute_flat_boundary / compute_regimes): a horizontal line
    separating flat spectra from the rest, a vertical band over the 'spheres'
    cluster, and a diagonal fit over the red-shifted 'disks' regime.
    """
    fig, ax = plt.subplots(figsize=(6.6, 4.9))
    ok = d[d.conv_status == "ok"]
    na = d[d.conv_status != "ok"]

    if regimes is not None:
        lo, hi = regimes["sphere_lmax"]
        ax.axvspan(lo, hi, color="#0072B2", alpha=0.08, zorder=0)
        ax.axvline(lo, color="#0072B2", lw=1, ls=":", alpha=0.6, zorder=1)
        ax.axvline(hi, color="#0072B2", lw=1, ls=":", alpha=0.6, zorder=1)
        ax.text((lo + hi) / 2, 0.97, "spheres", transform=ax.get_xaxis_transform(),
                ha="center", va="top", fontsize=9, color="#0072B2", fontweight="bold")
        dlo, dhi = regimes["disk_lmax"]
        xs = np.linspace(dlo, dhi, 20)
        ys = regimes["disk_slope"] * xs + regimes["disk_intercept"]
        band = DISK_BAND_K * regimes["disk_resid_std"]
        # shaded dispersion band (a 'rectangle' along the trend) instead of a bare
        # line -- a thin line overstates the precision of a r~0.6 relationship
        ax.fill_between(xs, ys - band, ys + band, color="#D55E00", alpha=0.15,
                        zorder=1, edgecolor="none")
        ax.plot(xs, ys, "--", color="#D55E00", lw=1.6, zorder=4)
        if DISK_SHOW_R:
            ax.annotate(f"disks (r = {regimes['disk_r']:.2f})", (xs[-1], ys[-1] + band),
                        xytext=(6, 2), textcoords="offset points", ha="left",
                        fontsize=9, color="#D55E00", fontweight="bold")
        else:
            ax.annotate("disks", (xs[-1], ys[-1] + band),
                        xytext=(6, 2), textcoords="offset points", ha="left",
                        fontsize=9, color="#D55E00", fontweight="bold")

    sc = ax.scatter(ok.lambda_max, ok.abs_max, c=ok.conv_time_s, cmap=GROWTH_CMAP,
                    norm=conv_norm(), s=46, edgecolor="white", linewidth=0.5, zorder=3)
    if len(na):
        ax.scatter(na.lambda_max, na.abs_max, facecolor="0.8", edgecolor="0.5",
                   s=46, linewidth=0.5, zorder=2,
                   label=f"not converged (n = {len(na)})")
        ax.legend(loc="upper right", fontsize=8)

    if flat_boundary is not None:
        ax.axhline(flat_boundary, color="k", lw=1, ls="--", zorder=1)
        ax.text(0.99, flat_boundary, "flat  |  grown", transform=ax.get_yaxis_transform(),
                ha="right", va="bottom", fontsize=7.5, color="0.35")

    cb = fig.colorbar(sc, ax=ax, ticks=[0, 5, 10, 15, 20, 60, 100, 150, 200])
    cb.set_label("growth time (s)")
    ax.set_xlabel(r"$\lambda_{\max}$ (nm)"); ax.set_ylabel(r"$A_{\max}$ (a.u.)")
    top = float(d.abs_max.max())
    ax.set_ylim(0, top * 1.12)             # headroom so the 'spheres' label clears points
    fig.tight_layout()
    return fig

def fig_flat(df, spectra):
    """Show the flat spectra and where they sit in the A_max-lambda_max plane."""
    flat = df[df.is_flat]; keep = df[~df.is_flat]
    fig, ax = plt.subplots(1, 2, figsize=(11, 4.3))
    for _, r in flat.iterrows():
        sp = spectra[r.filename]
        ax[0].plot(sp["wl"], sp["abs"][-1], lw=0.8, alpha=0.8)
    ax[0].axhline(0, color="k", lw=0.6, ls=":")
    ax[0].set_xlabel("Wavelength (nm)"); ax[0].set_ylabel("Absorbance (a.u.)")
    ax[0].set_title(f"(a) Flat spectra (std < {FLAT_STD_THR}, n = {len(flat)})")
    ax[1].scatter(keep.lambda_max, keep.abs_max, s=36, color="#0072B2",
                  alpha=0.7, edgecolor="white", linewidth=0.4, label="kept")
    ax[1].scatter(flat.lambda_max, flat.abs_max, s=60, facecolor="none",
                  edgecolor="#D55E00", linewidth=1.6, label="flat (flagged)")
    ax[1].set_xlabel(r"$\lambda_{\max}$ (nm)"); ax[1].set_ylabel(r"$A_{\max}$ (a.u.)")
    ax[1].set_title("(b) Flat samples in the descriptor plane"); ax[1].legend(fontsize=8)
    fig.suptitle(f"{DATASET}: flat-spectrum flagging", y=1.02,
                 fontsize=13, fontweight="bold")
    fig.tight_layout()
    return fig

# ── Exploration aids ──────────────────────────────────────────────────────────
def short_name(fn):
    """S14-M14_sample_12 -> S14-M14·s12 (compact label for annotations)."""
    return (fn.replace("_sample_", "·s").replace("_init_", "·i")
              .replace("_iter_", "·it"))

def scatter_amax_lmax_labelled(d, highlight=None):
    """Exploration copy of fig8 (A_max vs λmax, coloured by convergence time) with
    every sample annotated by name. `highlight` = filenames to ring (e.g. the
    representative samples of fig8c). Large + tiny font since ~100 labels overlap."""
    highlight = set(highlight or [])
    fig, ax = plt.subplots(figsize=(15, 10))
    ok = d[d.conv_status == "ok"]; na = d[d.conv_status != "ok"]
    sc = ax.scatter(ok.lambda_max, ok.abs_max, c=ok.conv_time_s, cmap="plasma",
                    norm=conv_norm(), s=44, edgecolor="white", linewidth=0.5, zorder=3)
    handles = []
    if len(na):
        handles.append(ax.scatter(na.lambda_max, na.abs_max, facecolor="0.8",
                       edgecolor="0.5", s=44, linewidth=0.5, zorder=2,
                       label=f"not converged (n = {len(na)})"))
    if highlight:
        h = d[d.filename.isin(highlight)]
        handles.append(ax.scatter(h.lambda_max, h.abs_max, s=320, facecolor="none",
                       edgecolor="black", linewidth=1.8, zorder=5,
                       label="representative (fig8c)"))
    if handles:
        ax.legend(handles=handles, loc="upper right", fontsize=10)
    cb = fig.colorbar(sc, ax=ax, ticks=[0, 5, 10, 15, 20, 60, 100, 150, 200])
    cb.set_label("growth time (s)")
    for _, r in d.iterrows():
        hi = r.filename in highlight
        ax.annotate(short_name(r.filename), (r.lambda_max, r.abs_max),
                    xytext=(3, 3), textcoords="offset points",
                    fontsize=(8 if hi else 4.5), color=("black" if hi else "0.25"),
                    fontweight=("bold" if hi else "normal"), zorder=6)
    ax.set_xlabel(r"$\lambda_{\max}$ (nm)"); ax.set_ylabel(r"$A_{\max}$ (a.u.)")
    fig.tight_layout(); return fig

def fig_sample_evolution(spectra, names, df, wl_range=EVOL_WL_RANGE,
                         sg_window=SG_WINDOW, sg_poly=SG_POLY):
    """### PLACEHOLDER ### Full spectra + time evolution of chosen representative
    samples. Set REPRESENTATIVE_SAMPLES to 4 filenames; each panel overlays every
    time-point spectrum (Savitzky-Golay smoothed) coloured from t=0 (dark) to
    convergence (yellow). x = wl_range; y = [0, max absorbance]. A legend box lists
    the pump flows (µL/s) used to generate the sample, read from the H5 via df."""
    names = [n for n in names if n in spectra]
    flows = df.set_index("filename")[QCOLS]
    ncol = 2; nrow = int(np.ceil(len(names) / ncol)) or 1
    fig, ax = plt.subplots(nrow, ncol, figsize=(5.2*ncol, 3.4*nrow), squeeze=False)
    ax = ax.ravel()
    for a, name in zip(ax, names):
        sp = spectra[name]; A = np.asarray(sp["abs"]); wl = sp["wl"]; t = np.asarray(sp["t"])
        m = (wl >= wl_range[0]) & (wl <= wl_range[1]); wlm = wl[m]
        win = min(sg_window, len(wlm) - (len(wlm) + 1) % 2)   # odd, <= len
        if win <= sg_poly: win = sg_poly + 1 + (sg_poly % 2)
        norm = mpl.colors.Normalize(t.min(), t.max()); ymax = 0.0
        for j in range(len(A)):
            s = savgol_filter(A[j][m], win, sg_poly)
            a.plot(wlm, s, color=mpl.cm.viridis(norm(t[j])), lw=0.6, alpha=0.85)
            ymax = max(ymax, s.max())
        a.set_xlim(*wl_range); a.set_ylim(0, ymax)
        a.set_xlabel("Wavelength (nm)"); a.set_ylabel("Absorbance (a.u.)")
        a.set_title(short_name(name), fontsize=10)
        # pump-flow legend box (µL/s), read from the H5; placed opposite the peak
        # so it does not mask the spectrum (left if the peak is red-shifted)
        env = savgol_filter(A[:, m].max(0), win, sg_poly)
        peak_wl = wlm[np.argmax(env)]
        left = peak_wl > 0.5 * (wl_range[0] + wl_range[1])
        q = flows.loc[name]
        txt = "\n".join(f"{REAGENTS[k]:>7s} {q[QCOLS[k]]:4.2f}" for k in range(5)) + "\n  (µL/s)"
        a.text(0.03 if left else 0.97, 0.96, txt, transform=a.transAxes,
               ha="left" if left else "right", va="top",
               fontsize=6.5, family="monospace",
               bbox=dict(boxstyle="round", fc="white", ec="0.7", alpha=0.85))
        sm = mpl.cm.ScalarMappable(norm=norm, cmap="viridis"); sm.set_array([])
        cb = fig.colorbar(sm, ax=a); cb.set_label("time (s)", fontsize=8)
    for a in ax[len(names):]: a.axis("off")
    fig.tight_layout(); return fig

def choose_representatives(df):
    """REPRESENTATIVE_SAMPLES if set, else 4 clean samples spanning the λmax range."""
    if REPRESENTATIVE_SAMPLES:
        return REPRESENTATIVE_SAMPLES
    clean = df[~df.is_flat].sort_values("lambda_max")
    return [clean.iloc[int(f*(len(clean)-1))].filename for f in (0.1, 0.4, 0.6, 0.9)]

# ----------------------------------------------------------------------------
# 4. Run
# ----------------------------------------------------------------------------
def main():
    print(f"Loading {DATASET} from {DATA_ROOT} ...")
    df, spectra = load_session(DATA_ROOT)
    df = add_chem_features(df)
    df = enrich_convergence(df, spectra)
    cmap_manip = manip_colors(df)
    print(f"Loaded {len(df)} samples:")
    print(df.manip.value_counts().to_string())
    print("\nConvergence status:")
    print(df.conv_status.value_counts().to_string())
    okc = df.loc[df.conv_status == "ok", "conv_time_s"]
    print(f"Convergence time (converged): median {okc.median():.1f} s "
          f"({okc.min():.1f}-{okc.max():.1f} s)")
    df.to_csv(FIG_DIR / f"{DATASET}_eda_table.csv", index=False)

    # flat-spectrum flagging + cleaned ML set
    print(f"\nFlat spectra (abs std < {FLAT_STD_THR}): {df.is_flat.sum()} / {len(df)}")
    flat_list = df.loc[df.is_flat, ["filename", "manip", "lambda_max", "abs_max",
                                    "abs_std", "conv_status"]].sort_values("abs_std")
    print(flat_list.to_string(index=False))
    flat_list.to_csv(FIG_DIR / f"{DATASET}_flat_spectra.csv", index=False)
    ml = df[~df.is_flat].reset_index(drop=True)
    ml.to_csv(FIG_DIR / f"{DATASET}_ml_set.csv", index=False)
    print(f"\nML set (flat removed): {len(ml)} samples "
          f"-> {DATASET}_ml_set.csv")

    print("\nGenerating figures ...")
    savefig(fig1_lmax_amax(df, cmap_manip),         "fig1_lmax_amax_distributions")
    savefig(fig2_spectra(df, spectra, cmap_manip),  "fig2_uvvis_spectra")
    savefig(fig3_kinetics(df, spectra),             "fig3_growth_kinetics")
    savefig(fig4_manip_variation(df, cmap_manip),   "fig4_manip_variability")
    savefig(fig5_coverage(df),                      "fig5_simplex_coverage")
    savefig(fig6_variogram(df),                     "fig6_composition_structure")
    savefig(fig7_knn_local(df),                     "fig7_knn_local_smoothness")
    flat_boundary = FLAT_GROWN_EXTMAX
    regimes = compute_regimes(df)
    print(f"\nFlat/grown Ext_max boundary: {flat_boundary:.3f} "
          f"(fixed; data-driven midpoint would be {compute_flat_boundary(df):.3f})")
    print(f"Disk regime {regimes['disk_lmax']} nm: r = {regimes['disk_r']:.2f} "
          f"(slope {regimes['disk_slope']:.4f} /nm, resid_std {regimes['disk_resid_std']:.3f})")
    savefig(scatter_amax_lmax(df, flat_boundary, regimes), "fig8_amax_lmax_convtime")
    reps = choose_representatives(df)
    print(f"Representative samples: {reps}")
    savefig(scatter_amax_lmax_labelled(df, reps),   "fig8b_amax_lmax_labelled")
    savefig(fig_sample_evolution(spectra, reps, df), "fig8c_sample_evolution")
    savefig(fig_flat(df, spectra),                  "fig_flat_spectra")
    savefig(scatter_amax_lmax(ml, None, regimes),   "fig9_amax_lmax_convtime_noflat")
    print(f"Done -> {FIG_DIR.resolve()}")

if __name__ == "__main__":
    main()
